{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Sertindole, a lipophilic chloro-substituted indole antipsychotic, has an oral bioavailability of about 75% in humans; its high transferability and shared indole/chloroaromatic features support high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "L-5-hydroxytryptophan, an indole amino acid with a carboxylic acid, has an absolute oral bioavailability of 49% in volunteers, supporting F ≥ 20% for the query's indole-acid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Tolfenamic acid, a chloro-substituted NSAID carboxylic acid, has an absolute oral bioavailability of 63.2% in healthy volunteers, directly supporting high F for the query's lipophilic acid phenotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "2,4-D, a small chlorinated aryloxyacetic acid, is rapidly and completely absorbed orally in humans, supporting high F for a chlorinated aromatic carboxylic acid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Indacaterol, an indole-containing drug, has an oral bioavailability of approximately 24% in humans, still above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Gabapentin, a small carboxylic acid drug, has an average oral bioavailability of 49% in humans, supporting high F despite wide interindividual variation.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Loratadine, a tricyclic chloroaromatic drug, has good oral bioavailability in healthy volunteers, supporting high F for the query's tricyclic chloroaromatic core.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a lipophilic chloro-substituted carbazole propionic acid (carprofen-like NSAID). Multiple high-transfer human experimental records show absolute oral bioavailability well above 20% for structurally related indole/carbazole acids, chlorinated aryl carboxylic acids, and tricyclic chloroaromatic drugs. No affirmative evidence indicates F < 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is present in the provided evidence.",
    "Some analogues are bases or zwitterions rather than lipophilic acids, so exact transporter or metabolic behavior may differ from the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

